        while ($offset < $size) {
            $written = fwrite($stream, substr($body, $offset));
            if (!$written) rd16_fail('write_failed');
            $offset += $written;
        }
        if (!fflush($stream)) rd16_fail('flush_failed');
    } finally { fclose($stream); }
