function rd16_hook_templates(string $root, array $rows, ?string $modification = null): void {
    $root=str_replace('\\','/',$root);
    if (count($rows)>1024) rd16_fail('hook_theme_settings_cap');
    $stores=[0=>[]];
    foreach ($rows as $row) {
        if (count($row)!==4 || (!is_string($row[0]) && !is_int($row[0])) || (string)(int)$row[0] !== (string)$row[0] || (int)$row[0]<0 || (int)$row[0]>2147483647) rd16_fail('hook_theme_store_invalid');
        [$store,$key,$value,$serialized]=$row; $store=(int)$store;
        if ((string)$serialized!=='0') rd16_fail('serialized_hook_theme_setting');
        if (!in_array($key,['config_theme','theme_default_directory'],true) || (!is_string($value) && $value!==null) || strlen((string)$value)>256) rd16_fail('hook_theme_setting_invalid');
        if (isset($stores[$store]) && array_key_exists($key,$stores[$store])) rd16_fail('duplicate_hook_theme_setting');
        $stores[$store][$key]=(string)$value;
    }
    foreach ($stores as $values) {
        $effective=array_replace($stores[0],$values);
        $theme=($effective['config_theme']??'')==='default'?($effective['theme_default_directory']??''):($effective['config_theme']??'');
        if (!preg_match('/^[A-Za-z0-9_-]{0,64}$/D',$theme)) rd16_fail('unsafe_hook_theme_segment');
        // Mirror vendor lookup exactly, with store-N values overlaid on store0.
        $base='catalog/view/template/';
        foreach (array_unique([$base.($theme===''?'':$theme.'/').'template/',$base.'default/template/',$base]) as $prefix) {
            foreach (['account/account.twig', 'account/order_list.twig', 'account/order_info.twig', 'account/order_history.twig', 'account/shell.twig', 'common/header.twig', 'common/pagination.twig'] as $view) {
                $path=rd16_walk($root,$prefix.$view);
                if ($modification!==null && strpos($path,str_replace('\\','/',$modification))===0) rd16_fail('hook_modification_redirect');
                if ($prefix!==$base && rd16_state($path)!=='absent') rd16_fail('alternate_hook_template');
            }
        }
    }
}

function rd16_hook_multiset(array $hooks): string {
    $expected=['catalog/view/account/account/before:extension/ps_enhanced_measurement/analytics/ps_enhanced_measurement.eventCatalogViewAccountAccountBefore', 'catalog/view/account/order_info/before:extension/ps_enhanced_measurement/analytics/ps_enhanced_measurement.eventCatalogViewAccountOrderInfoBefore', 'catalog/view/common/header/before:extension/ps_enhanced_measurement/analytics/ps_enhanced_measurement.eventCatalogViewCommonHeaderBefore', 'catalog/view/common/header/before:extension/ps_google_recaptcha/captcha/ps_google_recaptcha.eventCatalogViewCommonHeaderBefore', 'catalog/view/common/header/before:extension/ps_live_search/module/ps_live_search.eventCatalogViewCommonHeaderBefore'];
    sort($hooks,SORT_STRING); sort($expected,SORT_STRING);
    if ($hooks!==$expected) rd16_fail('reviewed_hook_set_changed');
    return hash('sha256',json_encode($hooks));
}

