        if (DIR_CACHE . 'template/' !== RD16_CACHE || !is_dir(RD16_CACHE) || is_link(rtrim(RD16_CACHE,'/')) || realpath(RD16_CACHE) !== rtrim(RD16_CACHE,'/')) rd16_fail('template_cache_mapping_changed');
