        $facts = ['root'=>$root,'php'=>PHP_VERSION,'cache'=>RD16_CACHE];
        if ($checkThemes) {
            if (!preg_match('/^[A-Za-z0-9_]+$/D', DB_PREFIX)) rd16_fail('db_prefix_invalid');
            mysqli_report(MYSQLI_REPORT_OFF);
            $db = new mysqli(DB_HOSTNAME, DB_USERNAME, DB_PASSWORD, DB_DATABASE, (int) DB_PORT);
            if ($db->connect_errno || !$db->set_charset('utf8mb4')) rd16_fail('metadata_unavailable');
            foreach (['theme'=>['route','status'], 'event'=>['trigger','action','status'], 'setting'=>['store_id','key','value','serialized'], 'layout_route'=>['store_id','layout_id','route'], 'layout_module'=>['layout_id','code','position','sort_order']] as $table=>$required) {
                $q = $db->query('SHOW COLUMNS FROM `' . DB_PREFIX . $table . '`');
                if (!$q) rd16_fail('metadata_schema_unavailable');
                $columns=[];
                while ($row=$q->fetch_assoc()) $columns[]=$row['Field'];
                $q->free();
                if (array_diff($required,$columns)) rd16_fail('metadata_schema_changed');
            }
            if (!$db->query('START TRANSACTION READ ONLY')) rd16_fail('readonly_transaction_unavailable');
            $q=$db->query("SELECT `store_id`,`key`,LEFT(`value`,257) AS `value`,`serialized` FROM `" . DB_PREFIX . "setting` WHERE `key` IN ('config_theme','theme_default_directory') ORDER BY `store_id`,`key` LIMIT 1025");
            if (!$q) rd16_fail('hook_theme_settings_unavailable');
            $hookSettings=[];
            while ($setting=$q->fetch_assoc()) {
                if (count($hookSettings)>=1024) rd16_fail('hook_theme_settings_cap');
                $hookSettings[]=[(string)$setting['store_id'],(string)$setting['key'],$setting['value'],(string)$setting['serialized']];
            }
            $q->free();
            rd16_hook_templates($root,$hookSettings,defined('DIR_MODIFICATION')?(string)DIR_MODIFICATION:null);
            $facts['hook_theme_settings_sha256']=hash('sha256',json_encode($hookSettings));
            $statement=$db->prepare('SELECT COUNT(*) FROM `' . DB_PREFIX . 'theme` WHERE `route` = ?');
            $route='';
            if (!$statement || !$statement->bind_param('s',$route)) rd16_fail('theme_check_unavailable');
            foreach (['account/account', 'account/order_list', 'account/order_info', 'account/order_history', 'account/shell', 'common/header', 'common/pagination'] as $route) {
                if (!$statement->execute() || !$statement->bind_result($count) || !$statement->fetch()) rd16_fail('theme_check_unavailable');
                if ((int)$count !== 0) rd16_fail('active_target_theme_override');
                $statement->free_result();
            }
            $statement->close();
            $statement=$db->prepare('SELECT `store_id`,`layout_id`,`route` FROM `' . DB_PREFIX . 'layout_route` WHERE ? LIKE `route` OR ? LIKE `route` ORDER BY `store_id`,`route`,`layout_id` LIMIT 2');
            $hub='account/order'; $edit='account/order.info';
            if (!$statement || !$statement->bind_param('ss',$hub,$edit) || !$statement->execute() || !$statement->bind_result($store,$layout,$layoutRoute)) rd16_fail('layout_check_unavailable');
            $layouts=[];
            while ($statement->fetch()) $layouts[]=[(int)$store,(int)$layout,(string)$layoutRoute];
            if ($statement->errno || $layouts!==[[0,6,'account/%']]) rd16_fail('account_layout_changed');
            $statement->close();
            $q=$db->query('SELECT `code`,`position`,`sort_order` FROM `' . DB_PREFIX . 'layout_module` WHERE `layout_id` = 6 ORDER BY `position`,`sort_order`,`code` LIMIT 2');
            if (!$q) rd16_fail('layout_modules_unavailable');
            $modules=[];
            while ($module=$q->fetch_assoc()) $modules[]=[(string)$module['code'],(string)$module['position'],(int)$module['sort_order']];
            $q->free();
            if ($modules!==[['ciaccountsidebar.account_sidebar','column_left',0]]) rd16_fail('account_layout_modules_changed');
            $facts['account_layout']=[0,6,'account/%','ciaccountsidebar.account_sidebar'];
            // Core theme handler is admitted through the zero-row checks above.
            // Any other enabled hook that can modify these views/controller stops apply.
            $q=$db->query('SELECT `trigger`,`action` FROM `' . DB_PREFIX . 'event` WHERE `status` = 1 ORDER BY `trigger`,`action` LIMIT 1025');
            if (!$q) rd16_fail('event_check_unavailable');
            $hooks=[]; $total=0;
            while ($event=$q->fetch_assoc()) {
                if (++$total > 1024) rd16_fail('event_metadata_cap');
                $eventCheck=rd16_event_check((string)$event['trigger'],(string)$event['action']);
                if (!$eventCheck['allowed']) rd16_fail('unadmitted_target_event');
                if ($eventCheck['relevant']) $hooks[]=(string)$event['trigger'] . ':' . (string)$event['action'];
            }
            $q->free();
            if (!$db->rollback()) rd16_fail('readonly_transaction_close_failed');
            $db->close();
            $facts['admitted_hook_sha256']=rd16_hook_multiset($hooks);
            $facts['target_theme_overrides']=0;
        }
        ob_end_clean();
        return $facts;
    } catch (Throwable $error) {
        while (ob_get_level()) ob_end_clean();
        if ($error instanceof RuntimeException && preg_match('/^[a-z_]+$/D',$error->getMessage())) throw $error;
        rd16_fail('runtime_admission_failed');
    }
}

function rd16_rollback_plan(string $root, string $backup, array $targets): array {
    $prefix=$root . '/_patch_backups/' . RD16_ID . '-';
    if (strpos($backup,$prefix)!==0 || !preg_match('/^[0-9]{8}T[0-9]{6}Z-[a-f0-9]{12}$/D',substr($backup,strlen($prefix))) || str_replace('\\','/',realpath($backup)?:'')!==$backup) rd16_fail('unsafe_backup_path');
    rd16_walk($root,substr($backup,strlen($root)+1));
    $manifest=$backup . '/manifest.json';
    if (rd16_state($manifest)==='absent') rd16_fail('backup_manifest_missing');
    $data=json_decode(file_get_contents($manifest),true);
    if (!is_array($data) || ($data['task']??'')!==RD16_ID || ($data['root']??'')!==$root || count($data['targets']??[])!==count($targets)) rd16_fail('backup_manifest_invalid');
    $plan=[];
    foreach ($targets as $i=>$contract) {
        $row=$data['targets'][$i];
        if (($row['path']??'')!==$contract['path'] || ($row['after']??'')!==$contract['after']) rd16_fail('backup_contract_mismatch');
        if ($contract['path']!==RD16_HEADER && ($row['before']??'')!==$contract['before']) rd16_fail('backup_before_contract_mismatch');
        $path=rd16_walk($root,$row['path']); $current=rd16_state($path);
        if ($current!==$row['before'] && $current!==$row['after']) rd16_fail('rollback_target_drift');
        if ($row['before']!=='absent') {
            $copy=$backup . '/original-' . $i;
            if (rd16_state($copy)!==$row['before']) rd16_fail('backup_hash_mismatch');
            if ($row['path']===RD16_HEADER && hash('sha256',rd16_header_normalize(file_get_contents($copy)))!==$contract['normalized_before']) rd16_fail('header_backup_contract_mismatch');
        }
        $row['current']=$current; $plan[]=$row;
    }
    return $plan;
}

